#include "ProjectArchive.h"
static void testProjectArchives(const File& root,Assets& assets){
    auto folder=root.getChildFile("archive-core-"+Uuid().toString());folder.createDirectory();auto writeAudio=[&](const File& file,float value){file.getParentDirectory().createDirectory();AudioBuffer<float> audio(2,4800);for(int ch=0;ch<2;++ch)for(int i=0;i<4800;++i)audio.setSample(ch,i,ch==0?value:-value*.5f);auto stream=file.createOutputStream();WavAudioFormat wav;std::unique_ptr<AudioFormatWriter> writer(stream?wav.createWriterFor(stream.get(),48000,2,24,{},0):nullptr);if(!writer)return false;stream.release();return writer->writeFromAudioSampleBuffer(audio,0,4800);};
    auto first=folder.getChildFile("A/hit.wav"),second=folder.getChildFile("B/hit.wav"),duplicate=folder.getChildFile("C/copy.wav");expect(writeAudio(first,.25f)&&writeAudio(second,.5f),"create archive stereo fixtures");duplicate.getParentDirectory().createDirectory();first.copyFileTo(duplicate);auto hash=SHA256(first).toHexString();
    auto p=emptyProject();p.title="Portable test";p.songMode=true;p.loop=false;p.bpm=120;p.patterns[0].colour=6;p.patterns[0].lanes[5]={{0,.1,60,.7f}};p.markers={{"verse","Verse",0,4,2}};p.notes="Preserve notes and sounds";
    for(int i=5;i<8;++i){auto& t=p.tracks[(size_t)i];t.instrument=Instrument::sample;t.samplePath=(i==5?first:i==6?first:duplicate).getRelativePathFrom(folder).replaceCharacter('\\','/');t.sampleStart=.01;t.sampleEnd=.08;t.sampleLoop=true;}p.tracks[5].mixer.stereo.enabled=true;p.tracks[5].mixer.stereo.width=.6f;Clip c;c.track=6;c.beat=.5;c.length=.15;c.audioPath=second.getRelativePathFrom(folder).replaceCharacter('\\','/');c.sourceOffset=.02;c.gain=.6f;c.fadeIn=.02;c.fadeOut=.03;p.clips.push_back(c);p.clips.push_back({5,0,0,4});auto before=JSON::toString(projectToJson(p));auto archive=folder.getChildFile("song.zip");
    expect(exportProjectArchive(p,folder,archive).wasOk(),"portable ZIP collects sampler and Playlist audio");ZipFile zip(archive);expect(zip.getNumEntries()==4,"archive deduplicates identical source bytes across file paths and shared references");expect(JSON::toString(projectToJson(p))==before&&SHA256(first).toHexString()==hash,"archive export preserves source project and audio bytes");
    auto imported=folder.getChildFile("Imported");File output;expect(importProjectArchive(archive,imported,output).wasOk()&&output==imported.getChildFile("project.pulse"),"archive imports into one newly published local folder");Project restored;expect(loadProject(output,restored).wasOk(),"imported archive is a standard native project");auto reference=absoluteAssets(p,folder),actual=absoluteAssets(restored,imported);for(auto& t:reference.tracks)t.samplePath.clear();for(auto& t:actual.tracks)t.samplePath.clear();for(auto& clip:reference.clips)clip.audioPath.clear();for(auto& clip:actual.clips)clip.audioPath.clear();expect(JSON::toString(projectToJson(reference))==JSON::toString(projectToJson(actual)),"archive preserves every non-path project field including colours ranges fades effects and markers");expect(restored.tracks[5].samplePath==restored.tracks[6].samplePath&&restored.tracks[5].samplePath==restored.tracks[7].samplePath&&restored.tracks[5].samplePath!=restored.clips[0].audioPath,"shared audio deduplicates while same-named different audio stays distinct");
    bool hashes=true;for(auto& row:projectAssets(restored,imported))if(row.file!=File())hashes&=row.file.existsAsFile()&&SHA256(row.file).toHexString()==row.file.getFileNameWithoutExtension();expect(hashes,"all imported audio bytes match content-addressed names");auto a=render(p,assets,folder,24000),b=render(restored,assets,imported,24000,127);bool same=true;for(int ch=0;ch<2;++ch)for(int i=0;i<24000;++i)same&=a.getSample(ch,i)==b.getSample(ch,i);expect(same&&a.getMagnitude(0,0,24000)>.001f,"imported sampler loops and Playlist audio render sample-exactly across callback sizes");
    auto sentinel=folder.getChildFile("sentinel.pulse");output=sentinel;expect(importProjectArchive(archive,imported,output).failed()&&output==sentinel&&imported.getChildFile("project.pulse").existsAsFile(),"existing import folder is never replaced and output remains unchanged");
    std::atomic<bool> cancel{true};auto bytes=SHA256(archive).toHexString();expect(exportProjectArchive(p,folder,archive,&cancel).failed()&&SHA256(archive).toHexString()==bytes,"cancelled packaging preserves an existing destination ZIP");auto cancelledFolder=folder.getChildFile("Cancelled");expect(importProjectArchive(archive,cancelledFolder,output,&cancel).failed()&&!cancelledFolder.exists()&&output==sentinel,"cancelled import publishes no directory or caller output");
    auto missing=p;missing.tracks[5].samplePath="missing.wav";expect(exportProjectArchive(missing,folder,archive).failed()&&SHA256(archive).toHexString()==bytes,"missing samples reject without replacing an existing archive");auto badRange=p;badRange.tracks[5].sampleEnd=3;expect(exportProjectArchive(badRange,folder,archive).failed()&&SHA256(archive).toHexString()==bytes,"out-of-file sampler selections reject before packaging");expect(exportProjectArchive(p,folder,first).failed()&&SHA256(first).toHexString()==hash,"archive destination cannot overwrite its source sample");auto blocker=folder.getChildFile("blocker");blocker.replaceWithText("keep");expect(exportProjectArchive(p,folder,blocker.getChildFile("song.zip")).failed()&&blocker.loadFileAsString()=="keep","archive write failure preserves existing filesystem data");
    auto emptyZip=folder.getChildFile("empty.zip");auto empty=emptyProject();expect(exportProjectArchive(empty,folder,emptyZip).wasOk()&&ZipFile(emptyZip).getNumEntries()==2,"synth-only projects need only project and checksum manifest");File emptyOutput;expect(importProjectArchive(emptyZip,folder.getChildFile("EmptyImported"),emptyOutput).wasOk(),"synth-only archive imports without a Samples folder");
    struct Entry{String name;MemoryBlock data;};std::vector<Entry> original;for(int i=0;i<zip.getNumEntries();++i){std::unique_ptr<InputStream> stream(zip.createStreamForEntry(i));Entry row{zip.getEntry(i)->filename,{}};stream->readIntoMemoryBlock(row.data);original.push_back(std::move(row));}
    auto setText=[](Entry& entry,const String& text){entry.data=MemoryBlock(text.toRawUTF8(),(size_t)text.getNumBytesAsUTF8());};auto text=[](const Entry& entry){return String::fromUTF8((const char*)entry.data.getData(),(int)entry.data.getSize());};
    auto rehash=[&](std::vector<Entry>& rows){auto* hashes=new DynamicObject();for(const auto& row:rows)if(row.name!="manifest.json")hashes->setProperty(row.name,SHA256(row.data).toHexString());auto* m=new DynamicObject();m->setProperty("schema",1);m->setProperty("format","pulse-project-archive");m->setProperty("files",var(hashes));for(auto& row:rows)if(row.name=="manifest.json")setText(row,JSON::toString(var(m),false));};
    auto writeZip=[&](const File& file,const std::vector<Entry>& rows){ZipFile::Builder builder;for(const auto& row:rows)builder.addEntry(std::make_unique<MemoryInputStream>(row.data,true),6,row.name,Time::getCurrentTime());FileOutputStream stream(file);return stream.openedOk()&&builder.writeToStream(stream,nullptr);};
    int index=0;auto rejected=[&](std::vector<Entry> rows,const char* name){auto file=folder.getChildFile("bad-"+String(++index)+".zip"),destination=folder.getChildFile("BadImported-"+String(index));expect(writeZip(file,rows),"write malformed archive fixture");output=sentinel;expect(importProjectArchive(file,destination,output).failed()&&!destination.exists()&&output==sentinel,name);};
    for(auto unsafe:{"../escape.wav","/absolute.wav","C:/outside.wav","Samples\\escape.wav","Samples/../project.pulse","Samples/abc.wav","PROJECT.PULSE"}){auto rows=original;rows.push_back({unsafe,MemoryBlock("bad",3)});rejected(std::move(rows),"unsafe or unexpected ZIP paths reject without publishing files");}
    auto rows=original;rows.push_back(rows.front());rejected(rows,"duplicate archive paths reject before import");rows=original;std::erase_if(rows,[](const Entry& e){return e.name=="manifest.json";});rejected(rows,"ZIP without Pulse checksum manifest rejects");rows=original;for(auto& e:rows)if(e.name=="manifest.json")setText(e,"{\"schema\":2}");rejected(rows,"unsupported archive manifest rejects");rows=original;for(auto& e:rows)if(e.name=="project.pulse")setText(e,"{}");rejected(rows,"tampered project checksum rejects");rows=original;for(auto& e:rows)if(e.name.startsWith("Samples/")){e.data=MemoryBlock("broken",6);break;}rejected(rows,"tampered audio checksum rejects");rehash(rows);rejected(rows,"audio hash in the stored filename remains authoritative after manifest changes");
    for(auto unsafe:{first.getFullPathName(),String("../outside.wav"),String("Samples/missing.wav")}){rows=original;for(auto& e:rows)if(e.name=="project.pulse"){auto json=JSON::parse(text(e));json["tracks"].getArray()->getReference(5).getDynamicObject()->setProperty("samplePath",unsafe);setText(e,JSON::toString(json,false));}rehash(rows);rejected(rows,"project references cannot escape the archive even with matching project checksum");}
    rows=original;std::erase_if(rows,[](const Entry& e){return e.name.startsWith("Samples/");});rehash(rows);rejected(rows,"missing referenced audio rejects despite a consistent file manifest");rows=original;for(auto& e:rows)if(e.name=="project.pulse")setText(e,"{}");rehash(rows);rejected(rows,"invalid native project rejects after valid ZIP checksum verification");
    rows=original;Entry extra;for(const auto& e:rows)if(e.name.startsWith("Samples/")){extra=e;break;}extra.name=extra.name.upToLastOccurrenceOf(".",false,false)+".flac";rows.push_back(extra);rehash(rows);rejected(rows,"unreferenced ZIP audio rejects instead of importing unrelated files");
    MemoryBlock raw;archive.loadFileAsData(raw);auto* data=static_cast<const uint8*>(raw.getData());size_t central=0;for(size_t i=0;i+46<raw.getSize();++i)if(ByteOrder::littleEndianInt(data+i)==0x02014b50){central=i;break;}
    auto corruptDirectory=[&](int offset,uint32 value,const char* name){auto copy=raw;auto* bytes=static_cast<uint8*>(copy.getData());for(int i=0;i<4;++i)bytes[central+(size_t)offset+(size_t)i]=(uint8)(value>>(i*8));auto file=folder.getChildFile("metadata-"+String(++index)+".zip");file.replaceWithData(copy.getData(),copy.getSize());auto dest=folder.getChildFile("MetadataImported-"+String(index));output=sentinel;expect(importProjectArchive(file,dest,output).failed()&&!dest.exists()&&output==sentinel,name);};
    expect(central>0,"locate ZIP metadata fixture");corruptDirectory(24,0x7fffffff,"oversized declared entry rejects before expansion");corruptDirectory(24,1,"underdeclared entry rejects without accepting truncated audio");corruptDirectory(38,0120777u<<16,"symbolic-link ZIP entry rejects without filesystem extraction");
    auto nonZip=folder.getChildFile("not-a-zip.zip");nonZip.replaceWithText("not a ZIP");expect(importProjectArchive(nonZip,folder.getChildFile("NonZip"),output).failed(),"ordinary non-ZIP input rejects");
    bool noPending=true;for(const auto& item:RangedDirectoryIterator(folder,false,".pulse-archive-*",File::findDirectories))noPending=false;expect(noPending,"failed cancelled and completed archive jobs clean their own staging folders");
}
